import icontract
from typing import List


@icontract.require(lambda a: len(a) > 0)
@icontract.ensure(lambda a, result: result + min(a) == max(a))
def differenceMinMax(a: List[int]) -> int:
    lo = a[0]
    hi = a[0]
    for x in a:
        if x < lo:
            lo = x
        if x > hi:
            hi = x
    return hi - lo
